 if(ET==='n'){const L=Object.keys(K.enc.n);b=L.length?L.map(n=>`<div class="fgIt"><div class="ic">👁️</div><div><b>${esc(n)}</b><small>${(CASE.find(c=>c.an===n)||{}).in?'พบในคดี「'+CASE.find(c=>c.an===n).n+'」':'พบระหว่างล่าในหมอก'}</small></div></div>`).join(''):'<p class="tag2">ยังไม่ได้บันทึก · เจอได้ระหว่างคดีหรือออกล่า</p>'}
