const DEEPX=[['กระบี่หักจากยุทธภพ','ด้ามยังพันผ้าแดง มีชื่อสำนักที่ไม่มีในเมืองนี้สลักอยู่','murim'],['ป้ายหยกของนิกายเซียน','เรืองแสงจางๆ เมื่อคุณหายใจใส่','xian'],['หมวกนักล่าจากนครกำแพง','มีรอยเขี้ยวอสูรและฝุ่นดาวตกติดอยู่','sky'],['วงแหวนวิญญาณที่แตก','ยังหมุนช้าๆ อยู่ในมือคุณ','soul'],['ป้ายชื่อพนักงานบริษัท','ภาษาเดียวกับคุณ แต่ตัวอักษรคมชัดเหมือนพิมพ์ด้วยเครื่องจักรที่เมืองนี้ยังไม่มี','mw'],['ผ้าถุงลายไทยเปียกน้ำ','มีเสียงหญิงร้องไห้ติดมากับมัน','ghost'],['ปลอกกระสุนจากโลกที่คนตายแล้วลุกขึ้นเดิน','ยังมีกลิ่นดินปืน','zombie']];
const DOOR={echo:['🗣️','ประตูที่มีเสียงพูดลอดออกมา'],relic:['📦','ประตูที่มีแสงสีแปลกตาลอดใต้บาน'],beast:['👁️','ประตูที่มีรอยข่วนจากด้านใน'],mem:['💭','ประตูที่มีกลิ่นบ้านของคุณ'],calm:['🕯️','ประตูที่เงียบสงบเหมือนห้องนอน'],mirror:['🪞','ประตูกระจกเงาทั้งบาน']};
function deepOpen(){const K=FG();if(!K)return;closeM();if(K.tier<2)return toast('ต้องข้ามธรณีที่ 2 ก่อนถึงจะลงห้วงใต้ได้');if(K.deepY===S.age)return toast('ปีนี้ลงห้วงใต้ไปแล้ว');K.deepY=S.age;deep(K,{d:0,loot:[],ins:0,cash:0})}
window.fogDeep=deepOpen;
function deep(K,R0){R0.d++;const d=R0.d;K.deepMax=Math.max(K.deepMax|0,d);if(d>=7)K.lore=Math.max(K.lore,7);
 const ks=shuf(Object.keys(DOOR).filter(k=>k!=='mirror'||d>=4)).slice(0,d>=3?3:2);
 const L=ks.map(k=>O(`${DOOR[k][0]} ${DOOR[k][1]}`,()=>room(K,R0,k),'',{echo:.5,relic:.6,beast:winP(threat(K)*(.7+d*.12),1)*.8,mem:.15,calm:K.anc<40?.9:.3,mirror:.35}[k]));
 L.push(O('🪜 ปีนกลับขึ้นไป',()=>deepEnd(K,R0,0),`พาของที่ได้กลับไป · ⚓ ตอนนี้ ${Math.round(K.anc)}`,K.anc<30||d>=5?.9:.15));
 C(`🕳️ ห้วงใต้ ชั้นที่ ${d}`,`ยิ่งลึก หมอกยิ่งข้นจนเหมือนน้ำ ของที่ถูกลืมจากหลายโลกลอยผ่านตัวคุณไป${d>=5?'<br><span class="tag2">⚠️ ลึกเกินกว่าที่ผู้ถือตราส่วนใหญ่เคยลงมา</span>':''}<br><span class="tag2">ทุกชั้นหลักยึด −${3+d} · ได้แล้ว: ${R0.loot.length?R0.loot.join(', '):'—'} · 🧩 +${R0.ins}</span>`,L)}
function room(K,R0,k){const d=R0.d;K.anc=cl(K.anc-(3+d),0,ancMax(K));try{window._fgSc='under'}catch(e){}
 const nx=()=>{if(K.anc<=5){say('🕳️ คุณลืมไปว่าตัวเองเป็นใครอยู่ครู่หนึ่ง เสียงของคนที่รักดึงคุณกลับขึ้นมา'+memLose(K,'จ่ายค่าทางขึ้นจากห้วงใต้'),'bad');return deepEnd(K,R0,1)}setTimeout(()=>deep(K,R0),400)};
 if(k==='echo'){if(rnd()<.55+d*.05){R0.ins++;feed(`🗣️ เสียงในห้องเล่าเรื่องที่ไม่มีใครในโลกบนรู้ · 🧩 +1`)}else feed('🗣️ เสียงพูดภาษาที่คุณไม่รู้จัก แล้วเงียบไป');return nx()}
 if(k==='relic'){const x=pick(DEEPX);if(d>=4&&rnd()<.35){const a=pick(['jade','star'].filter(z=>!K.arts.includes(z)));if(a){K.arts.push(a);encAdd('a',a);R0.loot.push(ART[a].n);feed(`📦 <b>${ART[a].n}</b> ลอยมาหาคุณเอง — ของจากโลกอื่นที่ใช้ได้จริง`);return nx()}}
  R0.loot.push(x[0]);R0.cash+=60*d;encAdd('n',x[0]);feed(`📦 คุณเจอ<b>${x[0]}</b> — ${x[1]} <span class="tag2">(ขายในตลาดมืดได้)</span>`);return nx()}
 if(k==='beast'){const nm=pick(['สิ่งที่กินชื่อคน','เงาของคนที่ไม่มีใครจำ','อสูรที่ตกลงมาจากฟ้าอีกโลก','ผีที่ลืมว่าตัวเองตาย']),ep=threat(K)*(.7+d*.12);if(fight(ep,1)){R0.ins++;R0.cash+=40*d;feed(`⚔️ คุณล้ม${nm}ได้ · 🧩 +1${fame(6*d)}`);encAdd('n',nm);return nx()}feed(`💥 ${nm}ลากคุณลงไปลึกกว่าเดิม${hurt(.25+d*.03)}`);if(S.hp<=S.maxHp*.15)return deepEnd(K,R0,1);return nx()}
 if(k==='mem'){C('💭 ห้องที่มีกลิ่นบ้าน','ในห้องมีความทรงจำของคุณลอยอยู่ ความทรงจำหนึ่งส่องแสงเหมือนกุญแจ',[O('แลกความทรงจำกับความจริง',()=>{R0.ins+=2;feed(`💭 ความทรงจำลอยออกไปจากหัว แลกกับความจริงสองชิ้น${memLose(K,'แลกกับห้วงใต้')} · 🧩 +2`);nx()},'',.3),O('เก็บความทรงจำไว้ เดินผ่านไป',()=>nx(),'',.7)]);return}
 if(k==='calm'){K.anc=cl(K.anc+8+d,0,ancMax(K));feed(`🕯️ ห้องนี้มีเตียงเก่าและตะเกียงที่ยังจุดอยู่ คุณนอนพักครู่หนึ่ง${anc(0)} · ⚓ ฟื้น`);return nx()}
 if(k==='mirror')return mirrorCity(K,()=>nx())}
function deepEnd(K,R0,forced){if(R0.cash)S.money+=R0.cash;K.ins+=R0.ins;try{window._fgSc=''}catch(e){}
 say(`🪜 ${forced?'คุณถูกดึงกลับขึ้นมา':'คุณปีนกลับขึ้นมาจากห้วงใต้'} ลึกสุด ${R0.d} ชั้น · 🧩 +${R0.ins}${R0.cash?' · 🪙 +'+fmt(R0.cash):''}${R0.loot.length?' · ของ: '+R0.loot.join(', '):''}`,R0.d>=5?'epic':'');render()}
