function endRec(K,id,quiet){try{const L=LS.get('murim_fogend',{})||{};if(!L[id]){L[id]=S.age;LS.set('murim_fogend',L);if(!quiet){}}K.ends=K.ends||[];if(!K.ends.includes(id))K.ends.push(id)}catch(e){}}
function endCheck(K){const ok=K.cases.filter(c=>c.r==='ok').length,wr=K.cases.filter(c=>c.r==='wrong').length;const add=id=>endRec(K,id,1);
 if(K.f.legend)add('legend');if(K.ser&&K.ser.done===1)add('ser');if(K.end)add(K.end);if(K.f.swallow||/เงาร้าง|เส้นด้าย/.test(S.deathCause||''))add('shade');if(S.spouse&&(S.kids|0)>0&&K.anc>=60)add('family');if(!S.spouse&&K.f.lostSp&&(!K.pt||!K.pt.alive))add('lonely');if(K.f.jailed||K.f.jail)add('jail');if(K.org&&K.org.lv>=3)add('org');if((K.frk|0)>=4)add('boss');if(K.dbl)add('spy');if(K.f.became)add('artifact');if(K.mem&&!K.mem.length)add('forget');if((K.deepMax|0)>=8)add('deep');if(!K.path&&ok>=5)add('normal');if(wr>=3)add('wrong');
 const pri=ENDS.find(e=>(K.ends||[]).includes(e[0]));return pri}
{const _cd=checkDeath;checkDeath=function(){try{const K=FG();if(K&&S&&S.alive&&S.deathCause&&!K.f.endShown){K.f.endShown=1;const e=endCheck(K);
  if(K.nar==='liar'&&(K.lies||[]).length)say(`🎭 <b>บทส่งท้าย: ผู้เล่าเรื่องโกหกคุณ</b><br>${K.lies.map(i=>'• '+LIES[i](K)[1]).join('<br>')}`,'myth');
  if(e)say(`🎬 <b>ตอนจบ: ${e[1]} ${e[2]}</b> — ${e[3]} <span class="tag2">(ปลดในคลังตอนจบแล้ว ${Object.keys(LS.get('murim_fogend',{})||{}).length}/${ENDS.length})</span>`,'myth',true)}}catch(x){console.error(x)}return _cd.apply(this,arguments)}}

