 if(x.nm.length)L.push(it('🕯️','นามต้องห้ามที่รู้',`<small>${x.nm.map(n=>`${n} (เอ่ยแล้ว ${x.nmC[n]|0})`).join(' · ')} · ราคาที่ยังค้าง ${x.nmD.length}</small>`));
